// Detect image format and build correct base64 data URL
const item = $input.first();
const binaryData = $('Convert Image to Base').first().binary;

// Try to get mime type from binary
let mimeType = 'image/jpeg'; // default
if (binaryData && binaryData.data0) {
  const bMime = binaryData.data0.mimeType || '';
  if (bMime.includes('png')) mimeType = 'image/png';
  else if (bMime.includes('webp')) mimeType = 'image/webp';
  else if (bMime.includes('gif')) mimeType = 'image/gif';
  else if (bMime.includes('jpeg') || bMime.includes('jpg')) mimeType = 'image/jpeg';
  else if (bMime) mimeType = bMime;
}

return [{
  json: {
    ...item.json,
    detectedMimeType: mimeType,
    imageDataUrl: `data:${mimeType};base64,${item.json.imageBase64}`
  }
}];

