const message = $input.item.json.choices?.[0]?.message?.content || '';

// Carry forward guest info from Extract Price node
let extractNode;
try {
  extractNode = $('Extract Price from Sheet').first().json;
} catch(e) {
  try {
    extractNode = $('Extract Price from Sheet').first().json;
  } catch(e2) {
    throw new Error('Cannot find Extract Price node!');
  }
}

// Get binary — try multiple source nodes
let receiptBinary = null;
let binaryKeyName = 'data0';

try {
  const hasReceiptNode = $('Has Receipt Image?').first();
  if (hasReceiptNode.binary && Object.keys(hasReceiptNode.binary).length > 0) {
    binaryKeyName = Object.keys(hasReceiptNode.binary)[0];
    receiptBinary = hasReceiptNode.binary[binaryKeyName];
  }
} catch(e) {}

if (!receiptBinary) {
  try {
    const binaryItem = $('Convert Image to Base').first();
    if (binaryItem.binary && Object.keys(binaryItem.binary).length > 0) {
      binaryKeyName = Object.keys(binaryItem.binary)[0];
      receiptBinary = binaryItem.binary[binaryKeyName];
    }
  } catch(e) {}
}

if (!receiptBinary) {
  try {
    const binaryItem = $('Convert Image to Base').first();
    if (binaryItem.binary && Object.keys(binaryItem.binary).length > 0) {
      binaryKeyName = Object.keys(binaryItem.binary)[0];
      receiptBinary = binaryItem.binary[binaryKeyName];
    }
  } catch(e) {}
}

let result;
try {
  const cleaned = message.replace(/```json|```/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  const errorItem = {
    json: {
      verified: false,
      is_receipt: false,
      amount_matches: false,
      extracted_amount: '0',
      reason: 'Could not parse vision model response: ' + message,
      guestName: extractNode.guestName,
      guestEmail: extractNode.guestEmail,
      roomType: extractNode.roomType,
      expectedPrice: extractNode.expectedPrice,
      sessionId: extractNode.sessionId,
      imageBase64: extractNode.imageBase64,
      binaryKeyName
    },
    binary: receiptBinary ? { [binaryKeyName]: receiptBinary } : {}
  };
  return [errorItem];
}

// STRICT math comparison
const extractedNum = parseFloat((result.extracted_amount || '0').replace(/[^0-9.]/g, ''));
const expectedNum = parseFloat(extractNode.expectedPrice);
const strictMatch = !isNaN(extractedNum) && !isNaN(expectedNum) && Math.abs(extractedNum - expectedNum) < 0.01;

const verified = result.is_receipt === true && strictMatch;

const outputItem = {
  json: {
    verified,
    is_receipt: result.is_receipt,
    amount_matches: strictMatch,
    extracted_amount: result.extracted_amount,
    reason: result.reason,
    guestName: extractNode.guestName,
    guestEmail: extractNode.guestEmail,
    roomType: extractNode.roomType,
    expectedPrice: extractNode.expectedPrice,
    sessionId: extractNode.sessionId,
    imageBase64: extractNode.imageBase64,
    binaryKeyName
  },
  binary: receiptBinary ? { [binaryKeyName]: receiptBinary } : {}
};

return [outputItem];

const sessionId = $('Parse Your YES or NO Reply').first().json.sessionId;
const isYes = $('Parse Your YES or NO Reply').first().json.isYes;
const sheetRows = $input.all();

let matchedRow = null;
for (const row of sheetRows) {
  // Try both 'session id' (lowercase) and 'Session ID' (capitals)
  const rowSession = (
    row.json['session id'] || 
    row.json['Session ID'] || 
    row.json['sessionId'] || 
    ''
  ).toString().trim();

  if (rowSession === sessionId) {
    matchedRow = row.json;
    break;
  }
}

if (!matchedRow) {
  return [{ json: { error: 'No booking found for this session', sessionId } }];
}

// Normalize all field names to handle spaces and casing
const guestName = (
  matchedRow['Guest Name'] || 
  matchedRow['Guest Name '] || 
  ''
).toString().trim();

const guestEmail = (
  matchedRow['Guest Email'] || 
  matchedRow['Guest Email '] || 
  ''
).toString().trim();

const roomType = (
  matchedRow['Standard Room'] || 
  matchedRow['Room Type'] || 
  ''
).toString().trim();

const price = (
  matchedRow['Price'] || 
  matchedRow['Price '] || 
  ''
).toString().trim();

return [{
  json: {
    guestName,
    guestEmail,
    roomType,
    price,
    isYes,
    sessionId
  }
}];

// Get image data
let imageData = {};
try {
  imageData = $('Convert Image to Base').first().json;
} catch(e) {
  try {
    imageData = $('Convert Image to Base').first().json;
  } catch(e2) {
    imageData = {};
  }
}
// Get binary image — try both node names
let receiptBinary = null;
try {
  const b = $('Convert Image to Base').first().binary;
  if (b && b.data0) receiptBinary = b.data0;
} catch(e) {
  try {
    const b = $('Convert Image to Base').first().binary;
    if (b && b.data0) receiptBinary = b.data0;
  } catch(e2) {
    receiptBinary = null;
  }
}
// Get the current guest's Session ID from Chat Trigger
let sessionId = '';
try {
  sessionId = $('Chat Trigger').first().json.sessionId || '';
} catch(e) {
  sessionId = '';
}
// Get ALL sheet rows
const sheetRows = $input.all();
let expectedPrice = '0';
let guestName = '';
let guestEmail = '';
let roomType = '';
let foundBySession = false;

// FIRST: Try to match by Session ID — if multiple rows match, pick the most recent one
if (sessionId) {
  let sessionMatches = [];

  for (const row of sheetRows) {
    const rowSession = (row.json['Session ID'] || '').toString().trim();
    if (rowSession === sessionId) {
      sessionMatches.push(row);
    }
  }

  if (sessionMatches.length > 0) {
    let latestRow = sessionMatches[0];
    let latestTime = latestRow.json['Booked At'] ? new Date(latestRow.json['Booked At']).getTime() : 0;

    for (const row of sessionMatches) {
      const t = row.json['Booked At'] ? new Date(row.json['Booked At']).getTime() : 0;
      if (t > latestTime) {
        latestTime = t;
        latestRow = row;
      }
    }

    const price = (latestRow.json['Price'] || latestRow.json['Price '] || '').toString().trim();
    const cleaned = price.replace(/[^0-9.]/g, '');
    if (cleaned) {
      expectedPrice = cleaned;
      guestName = (latestRow.json['Guest Name'] || latestRow.json['Guest Name '] || '').toString().trim();
      guestEmail = (latestRow.json['Guest Email'] || '').toString().trim();
      roomType = (latestRow.json['Standard Room'] || latestRow.json['Room Type'] || '').toString().trim();
      foundBySession = true;
    }
  }
}

// FALLBACK: latest Booked At timestamp
if (!foundBySession) {
  let latestTime = 0;
  for (const row of sheetRows) {
    const availability = (row.json['Availability'] || row.json['Availability '] || '').toString().trim().toLowerCase();
    const hasGuest = (row.json['Guest Email'] || '').toString().trim() !== '';
    const price = (row.json['Price'] || row.json['Price '] || '').toString().trim();
    const bookedAtRaw = row.json['Booked At'] || '';
    const bookedAt = bookedAtRaw ? new Date(bookedAtRaw).getTime() : 0;
    if (availability === 'no' && hasGuest && bookedAt > latestTime) {
      latestTime = bookedAt;
      const cleaned = price.replace(/[^0-9.]/g, '');
      if (cleaned) {
        expectedPrice = cleaned;
        guestName = (row.json['Guest Name'] || row.json['Guest Name '] || '').toString().trim();
        guestEmail = (row.json['Guest Email'] || '').toString().trim();
        roomType = (row.json['Standard Room'] || row.json['Room Type'] || '').toString().trim();
      }
    }
  }
}

// FINAL SAFETY CHECK
if (!expectedPrice || expectedPrice === '0') {
  throw new Error('Could not find expected price for this session. Session ID: ' + sessionId);
}

const outputItem = {
  json: {
    ...imageData,
    expectedPrice,
    sessionId,
    guestName,
    guestEmail,
    roomType,
    foundBySession
  }
};

// ALWAYS attach binary so email nodes never fail
if (receiptBinary) {
  outputItem.binary = { data0: receiptBinary };
}

return [outputItem];

const emailBody = ($input.item.json.text || $input.item.json.snippet || '').toString().toUpperCase().trim();
const subject = ($input.item.json.Subject || $input.item.json.subject || '').toString();

// Extract Session ID from subject — matches long UUID format
const sessionMatch = 
  subject.match(/Session ID[:\s]+([a-f0-9]{8,})/i) ||
  subject.match(/SESSION[:\s]+([a-f0-9]{8,})/i) ||
  subject.match(/([a-f0-9]{20,})/i);

const sessionId = sessionMatch ? sessionMatch[1].trim() : '';

const isYes = emailBody.startsWith('YES') || emailBody.includes('\nYES') || emailBody.includes('YES\n');
const isNo = emailBody.startsWith('NO') || emailBody.includes('\nNO') || emailBody.includes('NO\n');

return [{
  json: {
    isYes,
    isNo,
    sessionId,
    emailBody,
    subject
  }
}];
